import java.util.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
final class PoisonAtomicPatch implements Opcodes {
 static final String P="local/lito381/server/",C=P+"ClientSession",T=P+"BattleTimedStatus",H=P+"CombatPoisonAtomic",D=H+"$NpcState",K=P+"ClassicWorldMonsterPoisonAttack$Kind",ARGS="(JIIIJLjava/lang/String;)";
 static AbstractInsnNode before(AbstractInsnNode n){return DragonPatch.prior(n);}static AbstractInsnNode after(AbstractInsnNode n){return DragonPatch.next(n);}
 static void apply(ClassNode c,Map<String,Integer> hooks)throws AnalyzerException{
  var m=CombatPatch.method(c,"applyClassicWorldNpcPoison",ARGS+"V");AbstractInsnNode start=null,end=null;JumpInsnNode applied=null;
  for(var n:m.instructions)if(n instanceof MethodInsnNode call&&call.owner.equals(P+"ServerConfig")&&call.name.equals("classicWorldMonsterPoisonFixtureRoll")){start=before(before(call));if(!(after(call) instanceof VarInsnNode v)||v.getOpcode()!=ISTORE||v.var!=9)throw new IllegalStateException("NPC configured roll slot");}else if(n instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD&&f.owner.equals(C)&&f.name.equals("classicWorldPoisonKind")){end=n;}
  if(start==null||end==null)throw new IllegalStateException("native NPC poison state range missing");for(var n=end;n!=start;n=n.getPrevious())if(n instanceof JumpInsnNode j&&j.getOpcode()==IFEQ&&before(j) instanceof VarInsnNode v&&v.getOpcode()==ILOAD&&v.var==14){applied=j;break;}if(applied==null)throw new IllegalStateException("NPC applied gate missing");
  var clone=new MethodNode(ACC_PRIVATE,"sourceNpcPoisonState",ARGS+"L"+D+";",null,null);var labels=new HashMap<LabelNode,LabelNode>();for(var n:m.instructions)if(n instanceof LabelNode l)labels.put(l,new LabelNode());var result=new LabelNode();
  for(var n=start;;n=n.getNext()){if(!(n instanceof FrameNode)&&!(n instanceof LineNumberNode)){var copy=n.clone(labels);if(n==applied)((JumpInsnNode)copy).label=result;clone.instructions.add(copy);}if(n==end)break;}
  clone.instructions.add(result);clone.instructions.add(new TypeInsnNode(NEW,D));clone.instructions.add(new InsnNode(DUP));clone.instructions.add(new VarInsnNode(ALOAD,11));for(int slot:new int[]{10,12,13,14})clone.instructions.add(new VarInsnNode(ILOAD,slot));clone.instructions.add(new MethodInsnNode(INVOKESPECIAL,D,"<init>","(L"+K+";IZZZ)V",false));clone.instructions.add(new InsnNode(ARETURN));clone.maxLocals=m.maxLocals;clone.maxStack=m.maxStack+16;c.methods.add(clone);
  var replacement=new InsnList();replacement.add(new VarInsnNode(ALOAD,0));replacement.add(new VarInsnNode(LLOAD,1));for(int slot:new int[]{3,4,5})replacement.add(new VarInsnNode(ILOAD,slot));replacement.add(new VarInsnNode(LLOAD,6));replacement.add(new VarInsnNode(ALOAD,8));replacement.add(new MethodInsnNode(INVOKESTATIC,H,"npc","(L"+C+";JIIIJLjava/lang/String;)L"+D+";",false));String[] names={"kind","roll","resistance","existing","applied"};int[] slots={11,10,12,13,14};String[] returns={"L"+K+";","I","Z","Z","Z"};for(int i=0;i<5;i++){if(i<4)replacement.add(new InsnNode(DUP));replacement.add(new MethodInsnNode(INVOKEVIRTUAL,D,names[i],"()"+returns[i],false));replacement.add(new VarInsnNode(i==0?ASTORE:ISTORE,slots[i]));}replacement.add(new VarInsnNode(ILOAD,14));replacement.add(new JumpInsnNode(IFEQ,applied.label));m.instructions.insertBefore(start,replacement);for(var n=start;;){var next=n.getNext();m.instructions.remove(n);if(n==end)break;n=next;}
  int players=0,polls=0,writes=0;var fields=new TreeMap<String,Integer>();
  for(var method:new ArrayList<>(c.methods))if(!method.name.equals("sourceNpcPoisonState")&&!method.name.startsWith("<")){method.maxStack+=32;var nodes=method.instructions.toArray();var frames=new Analyzer<>(new SourceInterpreter()).analyze(c.name,method);for(int at=0;at<nodes.length;at++){var n=nodes[at];
   if(n instanceof MethodInsnNode call&&call.owner.equals(T)&&call.name.equals("activatePoison")&&call.desc.equals("(JII)Z")){
    var value=frames[at].getStack(frames[at].getStackSize()-4);if(value.insns.size()!=1||!(value.insns.iterator().next() instanceof FieldInsnNode field)||!field.owner.equals(C)||!field.name.equals("timedStatus")||!(before(field) instanceof VarInsnNode pc)||pc.getOpcode()!=ALOAD)throw new IllegalStateException("PC poison admission operand: "+method.name);var args=new InsnList();args.add(new VarInsnNode(ALOAD,pc.var));args.add(new VarInsnNode(ALOAD,0));method.instructions.insertBefore(call,args);method.instructions.set(call,new MethodInsnNode(INVOKESTATIC,H,"player","(L"+T+";JIIL"+C+";L"+C+";)Z",false));players++;
   }else if(n instanceof MethodInsnNode call&&method.name.equals("serverExpireTimedStatuses")&&call.owner.equals(T)&&call.name.equals("pollPoison")&&call.desc.equals("(JI)L"+T+"$PoisonPoll;")){method.instructions.insertBefore(call,new VarInsnNode(ALOAD,0));method.instructions.set(call,new MethodInsnNode(INVOKESTATIC,H,"poll","(L"+T+";JIL"+C+";)L"+T+"$PoisonPoll;",false));polls++;}
   else if(n instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD&&f.owner.equals(C)&&Set.of("poisonAttacker","classicWorldPoisonAttackerObjectId","classicWorldPoisonKind").contains(f.name)){String name=f.name.equals("poisonAttacker")?"attacker":f.name.equals("classicWorldPoisonKind")?"kind":"object";method.instructions.set(f,new MethodInsnNode(INVOKESTATIC,H,name,"(L"+C+";"+f.desc+")V",false));writes++;fields.merge(f.name,1,Integer::sum);}
  }
  }
  // Recompute only the split installer and its new scalar clone. The pinned
  // writer otherwise preserves formal stack maps; a cloned CFG needs its own.
  m.localVariables=null;var frameClass=new ClassNode();frameClass.version=c.version;frameClass.access=ACC_PUBLIC;frameClass.name=c.name;frameClass.superName=c.superName;frameClass.methods.add(m);frameClass.methods.add(clone);var frameWriter=new ClassWriter(ClassWriter.COMPUTE_FRAMES|ClassWriter.COMPUTE_MAXS);frameClass.accept(frameWriter);var framed=new ClassNode();new ClassReader(frameWriter.toByteArray()).accept(framed,0);for(var method:framed.methods){int index=c.methods.indexOf(method.name.equals("sourceNpcPoisonState")?clone:m);c.methods.set(index,method);}
  CombatPatch.require(players,3,"source shared PC poison admission transactions");CombatPatch.require(polls,1,"source poison poll/provenance transaction");System.out.println("source-poison-provenance-writes="+fields);hooks.put("source-poison-atomic-state",1+players+polls);hooks.put("source-poison-provenance-writes",writes);
 }
}
